def par(*r): return 1/sum(1/x for x in r)
def g(x): return '%.3g'%x
def add(t,l,b,**k):
    cnt[0]+=1; d=dict(t=t,l=l,b=b,fp='c4_%d'%cnt[0]); d.update(k); NEW.append(d)
def mcq(t,l,b,q,c,w3,w,sol): assert len(w3)==3; add(t,l,b,type='mcq',q=q,o=[c]+w3,w=w,sol=sol)
def num(t,l,b,q,v,u,w,sol,tol=0.02): add(t,l,b,type='short',q=q,num={"v":float('%.6g'%v),"tol":tol,"u":u},w=w,sol=sol)
def txt(t,l,b,q,a,w,sol): add(t,l,b,type='short',q=q,text=a,w=w,sol=sol)
def multi(t,l,b,q,o,a,w,sol): add(t,l,b,type='multi',q=q,o=o,a=a,w=w,sol=sol)
def order(t,l,b,q,items,w,sol): add(t,l,b,type='order',q=q,items=items,w=w,sol=sol)
def match(t,l,b,q,pairs,w,sol): add(t,l,b,type='match',q=q,pairs=pairs,w=w,sol=sol)
C='circ'; K='kirch'
def nodal(edges,n,fixed):
    G=np.zeros((n,n))
    for a,b,R in edges:
        G[a,a]+=1/R;G[b,b]+=1/R;G[a,b]-=1/R;G[b,a]-=1/R
    free=[i for i in range(n) if i not in fixed]; V=np.zeros(n)
    for k,v in fixed.items(): V[k]=v
    rhs=-G[np.ix_(free,list(fixed))]@np.array(list(fixed.values()))
    V[free]=np.linalg.solve(G[np.ix_(free,free)],rhs); return V

