# ===== KIRCH =====
def solve2(E1,R1,E2,R2,R3):
    Vn=(E1/R1+E2/R2)/(1/R1+1/R2+1/R3); return (E1-Vn)/R1,(E2-Vn)/R2,Vn/R3,Vn
